"use client"

import * as React from "react"
import { cn } from "cn"
import { SearchIcon, XIcon } from "lucide-react"

import { Button } from "@tecton/react/button"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@tecton/react/input-group"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@tecton/react/select"
import { Chip, ChipGroup, ChipList } from "@tecton/react/chip"

import { fields, statusMeta, typeMeta } from "../data"
import type { WellStatus, WellType } from "../data"

export type WellsFilter = {
  query: string
  field: string
  type: WellType | "all"
  statuses: WellStatus[]
}

export const emptyFilter: WellsFilter = {
  query: "",
  field: "all",
  type: "all",
  statuses: [],
}

const allStatuses = Object.keys(statusMeta) as WellStatus[]
const allTypes = Object.keys(typeMeta) as WellType[]

const fieldItems = [
  { value: "all", label: "All fields" },
  ...fields.map((field) => ({ value: field, label: field })),
]
const typeItems = [
  { value: "all", label: "All types" },
  ...allTypes.map((type) => ({ value: type, label: typeMeta[type] })),
]

type WellsFilterBarProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  value: WellsFilter
  onChange: (next: WellsFilter) => void
  /** Number of rows matching the current filter. */
  resultCount?: number
}

function WellsFilterBar({
  className,
  value,
  onChange,
  resultCount,
  ...props
}: WellsFilterBarProps) {
  const set = <TKey extends keyof WellsFilter>(
    key: TKey,
    next: WellsFilter[TKey]
  ) => onChange({ ...value, [key]: next })

  const active =
    value.query.trim() !== "" ||
    value.field !== "all" ||
    value.type !== "all" ||
    value.statuses.length > 0

  return (
    <div
      data-slot="wells-filter-bar"
      className={cn("flex flex-col gap-3", className)}
      {...props}
    >
      <div className="flex flex-col gap-3 md:flex-row md:items-end">
        <InputGroup className="md:max-w-xs">
          <InputGroupInput
            aria-label="Search wells"
            placeholder="Search by name, rig or operator…"
            value={value.query}
            onChange={(event) => set("query", event.target.value)}
          />
          <InputGroupAddon align="inline-start">
            <SearchIcon aria-hidden />
          </InputGroupAddon>
        </InputGroup>
        <Select
          value={value.field}
          onValueChange={(next) => set("field", next ?? "all")}
          items={fieldItems}
        >
          <SelectTrigger aria-label="Field" className="md:w-48">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {fieldItems.map((item) => (
              <SelectItem key={item.value} value={item.value}>
                {item.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Select
          value={value.type}
          onValueChange={(next) => set("type", next ?? "all")}
          items={typeItems}
        >
          <SelectTrigger aria-label="Well type" className="md:w-44">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {typeItems.map((item) => (
              <SelectItem key={item.value} value={item.value}>
                {item.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {active && (
          <Button
            variant="ghost"
            size="sm"
            className="md:ms-auto"
            onClick={() => onChange(emptyFilter)}
          >
            <XIcon /> Clear filters
          </Button>
        )}
      </div>

      <div className="flex flex-wrap items-center gap-2">
        <span className="text-xs text-muted-foreground">Status</span>
        <ChipGroup
          aria-label="Status filters"
          selectionMode="multiple"
          value={value.statuses}
          onValueChange={(next) =>
            set(
              "statuses",
              allStatuses.filter((status) => next.includes(status))
            )
          }
        >
          <ChipList>
            {allStatuses.map((status) => {
              const selected = value.statuses.includes(status)
              return (
                <Chip
                  key={status}
                  value={status}
                  size="md"
                  variant={selected ? statusMeta[status].color : "secondary"}
                  appearance={selected ? "solid" : "outline"}
                >
                  {statusMeta[status].label}
                </Chip>
              )
            })}
          </ChipList>
        </ChipGroup>
        {value.statuses.length > 0 && (
          <ChipGroup
            aria-label="Active status filters"
            className="ms-auto"
            onRemove={(removed) =>
              set(
                "statuses",
                value.statuses.filter((status) => !removed.includes(status))
              )
            }
          >
            <ChipList>
              {value.statuses.map((status) => (
                <Chip key={status} value={status}>
                  {statusMeta[status].label}
                </Chip>
              ))}
            </ChipList>
          </ChipGroup>
        )}
        {typeof resultCount === "number" && (
          <span className="ms-auto font-mono text-xs text-muted-foreground tabular-nums">
            {resultCount} {resultCount === 1 ? "well" : "wells"}
          </span>
        )}
      </div>
    </div>
  )
}

export { WellsFilterBar }
export type { WellsFilterBarProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import {
  DatabaseIcon,
  DownloadIcon,
  FolderPlusIcon,
  PlusIcon,
} from "lucide-react"

import { Button } from "@tecton/react/button"
import {
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "@tecton/react/dropdown-menu"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@tecton/react/empty"
import {
  createColumns,
  DataTable,
  DataTableActionBar,
  DataTableContent,
  DataTableFooter,
  DataTablePagination,
  DataTableRowActions,
} from "@tecton/react/data-table"
import { OverflowItem, OverflowLabel } from "@tecton/react/overflow"

import { statusMeta, typeMeta } from "../data"
import type { Well, WellStatus } from "../data"

const statusOptions = (Object.keys(statusMeta) as WellStatus[]).map(
  (status) => ({
    value: status,
    label: statusMeta[status].label,
    variant: statusMeta[status].color,
  })
)

/** Numbers and dates in the reader's locale, set in mono like the well names. */
function mono(_: Well, { text }: { text: string }) {
  return <span className="font-mono tabular-nums">{text}</span>
}

function createWellColumns(onOpen?: (well: Well) => void) {
  return createColumns<Well>([
    {
      id: "name",
      header: "Well",
      cell: (well) => (
        <span className="font-mono font-medium tabular-nums">{well.name}</span>
      ),
    },
    { id: "field", header: "Field", hideBelow: "sm" },
    {
      id: "type",
      header: "Type",
      accessor: (well) => typeMeta[well.type],
      hideBelow: "md",
    },
    { id: "status", header: "Status", type: "options", options: statusOptions },
    { id: "td", header: "TD (m MD)", type: "number", cell: mono },
    {
      id: "spud",
      header: "Spud",
      type: "date",
      // The ISO date is a calendar day: read and shown in UTC.
      accessor: (well) => new Date(`${well.spud}T00:00:00Z`),
      format: {
        day: "2-digit",
        month: "short",
        year: "numeric",
        timeZone: "UTC",
      },
      cell: mono,
      hideBelow: "lg",
    },
    { id: "rig", header: "Rig", hideBelow: "lg" },
    {
      id: "actions",
      header: "Actions",
      renderHeader: () => <span className="sr-only">Actions</span>,
      align: "end",
      sortable: false,
      hideable: false,
      cell: (well) => (
        <DataTableRowActions aria-label={`Actions for ${well.name}`}>
          <DropdownMenuItem onClick={() => onOpen?.(well)}>
            Open
          </DropdownMenuItem>
          <DropdownMenuItem>Add to project</DropdownMenuItem>
          <DropdownMenuItem>Export logs</DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="destructive">Archive</DropdownMenuItem>
        </DataTableRowActions>
      ),
    },
  ])
}

const pageSizeOptions = [10, 25, 50, 100]

type WellsTableProps = Omit<React.ComponentProps<"div">, "defaultValue"> & {
  data: Well[]
  onOpen?: ((well: Well) => void) | undefined
  /** Rows per page at first; the reader changes it in the footer. */
  pageSize?: number
  /** Called with the ids of the selected wells. */
  onSelectionChange?: (ids: ReadonlyArray<string>) => void
}

/**
 * Paginated, sortable, selectable wells table on `DataTable`. A header
 * sorts its column, a row's checkbox selects it, and Enter, a double
 * click or a click while nothing is selected opens the well; the row's
 * actions menu opens it too. While wells are selected, an action bar
 * offers to add them to a project or export their logs. On narrow
 * viewports the less important columns hide.
 */
function WellsTable({
  className,
  data,
  onOpen,
  pageSize = 10,
  onSelectionChange,
  ...props
}: WellsTableProps) {
  const columns = React.useMemo(() => createWellColumns(onOpen), [onOpen])

  return (
    <DataTable
      items={data}
      columns={columns}
      selectionMode="multiple"
      pagination
      defaultPageSize={pageSize}
      pageSizes={pageSizeOptions}
      striped
      {...(onSelectionChange === undefined
        ? {}
        : { onValueChange: (ids) => onSelectionChange(ids) })}
      {...(onOpen === undefined
        ? {}
        : { onActivate: (_: string, well: Well) => onOpen(well) })}
      className={cn("w-full", className)}
      {...props}
    >
      <DataTableActionBar aria-label="Selected wells">
        <OverflowItem
          value="project"
          label="Add to project"
          icon={<FolderPlusIcon />}
        >
          <Button variant="outline" size="sm">
            <FolderPlusIcon data-icon="inline-start" />
            <OverflowLabel>Add to project</OverflowLabel>
          </Button>
        </OverflowItem>
        <OverflowItem
          value="export"
          label="Export logs"
          icon={<DownloadIcon />}
        >
          <Button variant="outline" size="sm">
            <DownloadIcon data-icon="inline-start" />
            <OverflowLabel>Export logs</OverflowLabel>
          </Button>
        </OverflowItem>
      </DataTableActionBar>
      <DataTableContent aria-label="Wells" />
      <DataTableFooter>
        <DataTablePagination />
      </DataTableFooter>
    </DataTable>
  )
}

type WellsEmptyStateProps = React.ComponentProps<typeof Empty> & {
  /** True when a filter is active (offers "clear filters" instead of "add well"). */
  filtered?: boolean
  onClear?: () => void
  onCreate?: () => void
}

function WellsEmptyState({
  className,
  filtered = false,
  onClear,
  onCreate,
  ...props
}: WellsEmptyStateProps) {
  return (
    <Empty
      data-slot="wells-empty-state"
      className={cn(
        "rounded-md border border-dashed border-border bg-card/50",
        className
      )}
      {...props}
    >
      <EmptyHeader>
        <EmptyMedia variant="icon">
          <DatabaseIcon />
        </EmptyMedia>
        <EmptyTitle>{filtered ? "No wells match" : "No wells yet"}</EmptyTitle>
        <EmptyDescription>
          {filtered
            ? "Try a different search term, or clear the field, type and status filters."
            : "Import wells from the corporate database or create the first planned well."}
        </EmptyDescription>
      </EmptyHeader>
      <EmptyContent className="flex-row justify-center">
        {filtered ? (
          <Button
            variant="outline"
            size="sm"
            {...(onClear === undefined ? {} : { onClick: onClear })}
          >
            Clear filters
          </Button>
        ) : (
          <>
            <Button variant="outline" size="sm">
              Import
            </Button>
            <Button
              size="sm"
              {...(onCreate === undefined ? {} : { onClick: onCreate })}
            >
              <PlusIcon /> New well
            </Button>
          </>
        )}
      </EmptyContent>
    </Empty>
  )
}

export { WellsTable, WellsEmptyState, createWellColumns }
export type { WellsTableProps, WellsEmptyStateProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import { DownloadIcon, PlusIcon, UploadIcon } from "lucide-react"

import { Button } from "@tecton/react/button"
import {
  PageHeader,
  PageHeaderActions,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderEyebrow,
  PageHeaderTitle,
} from "@tecton/react/page-header"

import { emptyFilter, WellsFilterBar } from "./components/wells-filter-bar"
import type { WellsFilter } from "./components/wells-filter-bar"
import { WellsEmptyState, WellsTable } from "./components/wells-table"
import { wells as allWells } from "./data"
import type { Well } from "./data"

type WellsListPageProps = React.ComponentProps<"div"> & {
  wells?: Well[]
  /** Render the empty-state variant (no wells at all). */
  empty?: boolean
  onOpen?: (well: Well) => void
}

function applyFilter(wells: Well[], filter: WellsFilter): Well[] {
  const query = filter.query.trim().toLowerCase()
  return wells.filter((well) => {
    if (filter.field !== "all" && well.field !== filter.field) return false
    if (filter.type !== "all" && well.type !== filter.type) return false
    if (filter.statuses.length > 0 && !filter.statuses.includes(well.status))
      return false
    if (
      query &&
      ![well.name, well.rig, well.operator, well.field].some((text) =>
        text.toLowerCase().includes(query)
      )
    )
      return false
    return true
  })
}

/**
 * Wells list page — page header with actions, a filter bar (search,
 * selects, status chips) and a paginated, sortable, selectable `DataTable`,
 * with an empty state for no data / no matches.
 */
function WellsListPage({
  className,
  wells = allWells,
  empty = false,
  onOpen,
  ...props
}: WellsListPageProps) {
  const [filter, setFilter] = React.useState<WellsFilter>(emptyFilter)
  const source = empty ? [] : wells
  const rows = React.useMemo(
    () => applyFilter(source, filter),
    [source, filter]
  )
  const filtered = JSON.stringify(filter) !== JSON.stringify(emptyFilter)

  return (
    <div
      data-slot="wells-list-page"
      className={cn(
        "flex min-h-svh w-full flex-col gap-6 bg-background px-4 py-8 text-foreground md:px-8",
        className
      )}
      {...props}
    >
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderEyebrow>Inventory</PageHeaderEyebrow>
          <PageHeaderTitle>Wells</PageHeaderTitle>
          <PageHeaderDescription>
            All wells across your licences. Select rows to add them to a project
            or export their logs.
          </PageHeaderDescription>
        </PageHeaderContent>
        <PageHeaderActions>
          <Button variant="ghost" size="sm">
            <DownloadIcon /> Export
          </Button>
          <Button variant="outline" size="sm">
            <UploadIcon /> Import
          </Button>
          <Button size="sm">
            <PlusIcon /> New well
          </Button>
        </PageHeaderActions>
      </PageHeader>

      {source.length > 0 && (
        <WellsFilterBar
          value={filter}
          onChange={setFilter}
          resultCount={rows.length}
        />
      )}

      {rows.length === 0 ? (
        <WellsEmptyState
          filtered={source.length > 0 && filtered}
          onClear={() => setFilter(emptyFilter)}
        />
      ) : (
        <WellsTable data={rows} onOpen={onOpen} />
      )}
    </div>
  )
}

/** Route-ready page. */
export default function WellsListRoute() {
  return <WellsListPage />
}

export {
  WellsListPage,
  WellsFilterBar,
  WellsTable,
  WellsEmptyState,
  applyFilter,
}
export { wells, statusMeta, typeMeta, fields, formatDate } from "./data"
export { emptyFilter } from "./components/wells-filter-bar"
export type { WellsListPageProps }
export type { WellsFilter } from "./components/wells-filter-bar"
export type { Well, WellStatus, WellType } from "./data"
